```python
def generate_paragraph_html(text, class_name=None, text_color=None):
    html = f"<p"
    if class_name:
        html += f" class='{class_name}'"
    if text_color:
        html += f" style='color:{text_color};'"
    html += f">{text}</p>"
    return html
